insert into public.projects (slug,title,title_en,client,year,category,services,summary,problem,insight,idea,result,metrics,thumbnail_url,cover_url,gallery,featured,published,sort_order) values ('narrative-seongsu-ooh','명함으로는 닿지 못할 사이가 있습니다','Look Up, Seongsu','내러티브 홀딩컴퍼니 · Narrative Club',2026,'OOH',array['OOH','Visual Design','IMC']::text[],'성수 클럽하우스 외벽 5,350×5,750mm. 고개를 들어야 완성되는 광고.','창업가·크리에이터를 위한 프라이빗 멤버십 클럽. "들어와 봐야 아는" 가치를 길 위에서 어떻게 보여줄 것인가.','3.5m 폭 보도 위에서 사람들은 위를 보지 않는다. 대신 한 번 고개를 든 사람은 그 장면을 찍는다.','외벽 위로 2.5m 벌룬을 띄우고, 극단적인 로우앵글 인물을 배치했다. 보행자가 70° 이상 고개를 젖혀야 비로소 하나의 장면이 완성된다.','광고비 없이 6개 이상의 매거진에 소개되었다. 2026.11.03 설치.','[{"label":"외벽 배너","value":"5,350×5,750mm"},{"label":"시선 각도","value":"70°+"},{"label":"무가 매거진 노출","value":"6+"}]'::jsonb,'/media/narrative-ooh-1.jpg','/media/narrative-ooh-1.jpg','["/media/narrative-ooh-2.jpg","/media/narrative-ooh-3.jpg","/media/narrative-mock.jpg"]'::jsonb,true,true,1) on conflict (slug) do nothing;
insert into public.projects (slug,title,title_en,client,year,category,services,summary,problem,insight,idea,result,metrics,thumbnail_url,cover_url,gallery,featured,published,sort_order) values ('the-hackathon','흑백개발자: THE 해커톤','Black & White Developers','THE HACK',2026,'SNS',array['SNS Marketing','Web','Offline PR']::text[],'국회의원부터 토스 리더까지 참가한 해커톤. 후반 마케팅을 총괄했다.','본편 영상이 공개되기 전까지, 해커톤이라는 낯선 포맷에 사람들이 관심을 이어가게 만들어야 했다.','개발자에게 가장 익숙한 키는 F12다. 경쟁은 클릭 한 번으로 시작될 수 있다.','F12 키캡을 누르는 클릭 레이스 웹사이트를 만들고, 레이스가 끝나면 본편 영상으로 유입되게 설계했다. 티저 캐러셀·릴스, 스폰서 모집, 우승자 예측 이벤트를 함께 운영했다.','EO · BZCF · 더해커톤 유튜브에서 본편이 공개됐다. 시사회와 대학생 서포터즈로 온라인의 화제를 현장으로 이었다.','[{"label":"캠페인 기간","value":"07.09–08.15"},{"label":"시사회 참석","value":"≈60"}]'::jsonb,'/media/hackathon-keycap.jpg','/media/hackathon-keycap.jpg','["/media/hackathon-phone.png","/media/hackathon-screening-1.jpg","/media/hackathon-supporters.jpg"]'::jsonb,true,true,2) on conflict (slug) do nothing;
insert into public.projects (slug,title,title_en,client,year,category,services,summary,problem,insight,idea,result,metrics,thumbnail_url,cover_url,gallery,featured,published,sort_order) values ('tiro-sagwan','이제 TIRO 하나로 든든하게 회의 감!','The Royal Scribe','더플레이토 · Tiro',2026,'OOH',array['OOH','DOOH','Film']::text[],'조선의 사관(史官)이 회의록을 쓴다면. 98% 정확도의 AI 노트테이커.','AI 회의록 서비스는 많다. 기능 나열로는 아무도 기억하지 않는다.','왕의 말을 한 글자도 빠짐없이 받아 적던 사람이 있었다. 사관이다.','사극 일러스트 4종으로 강남 OOH를 만들고, 버스 광고에는 "미팅까지 세 정거장. 저번 미팅 결론을 다시 듣기엔 충분합니다."를 걸었다. 명화 속 인물이 회의를 하는 스토리보드로 DOOH·SNS 영상까지 확장했다.','영상은 THE 해커톤 본편 미드롤로 집행되었다.','[{"label":"정확도","value":"98%"},{"label":"실시간 번역","value":"17개 국어"},{"label":"전사 속도","value":"0.5s"}]'::jsonb,'/media/tiro-kv.jpg','/media/tiro-kv.jpg','["/media/tiro-gangnam.jpg","/media/tiro-sagwan-1.jpg","/media/tiro-sagwan-2.jpg","/media/tiro-bus.jpg","/media/tiro-film.jpg"]'::jsonb,true,true,3) on conflict (slug) do nothing;
insert into public.projects (slug,title,title_en,client,year,category,services,summary,problem,insight,idea,result,metrics,thumbnail_url,cover_url,gallery,featured,published,sort_order) values ('lockin-coffee','제갈궁뎅','Lock In Coffee Character IP','더존바이오 · 락인커피',2026,'Design',array['Character','SNS Branding']::text[],'카페인 중독 없이 건강하게 몰입한다. 노루궁뎅이버섯에서 태어난 캐릭터.','기능성 버섯커피는 설명이 길다. 설명하는 순간 매력이 사라진다.','원료 이름이 이미 웃기다. 노루궁뎅이버섯.','버섯을 지략가로 만든 캐릭터 ''제갈궁뎅''. 몰입을 돕는 책사라는 설정으로 SNS 톤까지 설계했다.',null,'[]'::jsonb,'/media/lockin-mock.jpg','/media/lockin-mock.jpg','["/media/lockin-character.png"]'::jsonb,true,true,4) on conflict (slug) do nothing;
insert into public.projects (slug,title,title_en,client,year,category,services,summary,problem,insight,idea,result,metrics,thumbnail_url,cover_url,gallery,featured,published,sort_order) values ('korean-amirsho','조금 유별난 한국인의 K-굿즈','Korean Amirsho Goods','@amirsho_kh',2026,'Design',array['Goods','Influencer']::text[],'아뇨아뇨아뇨 티셔츠부터 아미쇼당기쇼 키링까지. 팬이 먼저 웃는 굿즈.',null,null,'크리에이터의 유행어를 그대로 제품 이름으로. 티셔츠, 포토카드 7종, 안대, 키링 라인업을 기획·디자인했다.',null,'[]'::jsonb,'/media/amirsho-mock.jpg','/media/amirsho-mock.jpg','["/media/amirsho-lineup.jpg"]'::jsonb,false,true,5) on conflict (slug) do nothing;
insert into public.projects (slug,title,title_en,client,year,category,services,summary,problem,insight,idea,result,metrics,thumbnail_url,cover_url,gallery,featured,published,sort_order) values ('narrative-club-content','와인을 만나고 취향을 나누는 하루','Narrative Club Content','내러티브 홀딩컴퍼니 · Narrative Club',2026,'SNS',array['SNS','Contents Design','Event']::text[],'멤버십 클럽의 인스타그램과 이벤트 콘텐츠 총괄.',null,null,'런칭 와인 통합 시음회 등 이벤트 사진·영상 스케치와 인쇄·온라인 콜래터럴을 하나의 톤으로 묶었다.',null,'[]'::jsonb,'/media/narrative-event.jpg','/media/narrative-event.jpg','["/media/narrative-collateral.jpg","/media/narrative-apparel.jpg"]'::jsonb,false,true,6) on conflict (slug) do nothing;
insert into public.projects (slug,title,title_en,client,year,category,services,summary,problem,insight,idea,result,metrics,thumbnail_url,cover_url,gallery,featured,published,sort_order) values ('hackathon-screening','콘텐츠가 콘텐츠를 낳는 밤','THE Hackathon Screening Party','THE HACK',2026,'Offline',array['Offline Event','Influencer']::text[],'약 60명이 모인 시사회. 인플루언서와 매거진이 무가로 함께했다.',null,null,'현장의 경험이 다시 콘텐츠가 되도록 게스트를 설계했다. 330만 크리에이터부터 AI 전문 채널까지.',null,'[]'::jsonb,'/media/hackathon-screening-1.jpg','/media/hackathon-screening-1.jpg','["/media/hackathon-screening-2.jpg","/media/hackathon-screening-3.jpg"]'::jsonb,false,true,7) on conflict (slug) do nothing;
insert into public.projects (slug,title,title_en,client,year,category,services,summary,problem,insight,idea,result,metrics,thumbnail_url,cover_url,gallery,featured,published,sort_order) values ('nego-bi','와이너리의 시작과 끝을 잇다','Négo Brand Identity','Négo',2026,'Design',array['BI','Social Rebranding']::text[],'와인 브랜드의 BI와 소셜 리브랜딩 제안. 와인 버건디와 오크 캐스크 베이지.',null,null,null,null,'[]'::jsonb,'/media/nego-bi.jpg','/media/nego-bi.jpg','[]'::jsonb,false,true,8) on conflict (slug) do nothing;
